(function(){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cleanup=()=>{};
const copy=x=>structuredClone(x);
function mode(ch,n){if(ch==='pl07'){if(n<=12||n>=19&&n<=22)return 'lexer';if(n<=18)return 'regex';if(n<=31||n===58)return 'derive';if(n<=49)return 'tree';return 'ebnf';}if(n>=28&&n<=38)return 'scope';if(n>=43&&n<=47)return 'overload';if(n>=67&&n<=68||n>=72&&n<=84)return 'memory';if(n>=15&&n<=27||n>=39&&n<=41||n>=50&&n<=57||n===62)return 'block';if(n>=7&&n<=13||n===49||n>=58&&n<=66)return 'binding';return null;}
const titles={lexer:'字符→토큰: scanner 따라가기'.replace('字符','문자'),regex:'패턴 검사: 입력을 한 단계씩 대조',derive:'생성규칙 적용: 문장이 만들어지는 과정',tree:'AST 연결과 연산 결과 추적',ebnf:'EBNF 반복·선택 경로 걷기',scope:'정적·동적 범위: 이름이 선택하는 객체',memory:'환경→힙: 공유·복사·해제 추적',block:'블록 진입·종료: 이름과 수명 추적',binding:'환경·메모리: 어느 연결이 바뀔까?',overload:'오버로드 후보를 조건으로 좁히기'};
function controls(kind,ch,n){const text=(label,id,value)=>`<label>${label}<input id="pl-${id}" value="${esc(value)}" maxlength="100"></label>`;switch(kind){case 'lexer':return text('작은 scanner의 입력','input','* + ( ) 42 # 345');case 'regex':return `<label>패턴<select id="pl-pattern"><option value="digits">숫자 한 개 이상 [0-9]+</option><option value="id">C 형태 식별자</option><option value="mail">강의의 단순 이메일</option></select></label>`+text('검사할 문자열','input','count2');case 'derive':return `<label>생성할 문장<select id="pl-sentence"><option value="girl">the girl sees a dog .</option><option value="dog">a dog pets the girl .</option><option value="list">a,b,c 식별자 목록</option></select></label>`;case 'tree':return text('산술식 · 정수, +, *, 괄호','input',n===38||n===39?'3+4*5+6*7':n===40||n===41?'3*4+5*6+7':'3+4*5')+`<label>모호성 비교 모델<select id="pl-order"><option value="normal">곱셈 우선</option><option value="alternate">덧셈을 먼저 묶는 비교</option></select></label>`;case 'ebnf':return text('만들 숫자 · 1~8자리','input','345')+`<label>경로<select id="pl-path"><option value="number">number → digit {digit}</option><option value="if">if 문 · else 없음</option><option value="else">if 문 · else 포함</option></select></label>`;case 'scope':return `<label>이름 탐색 규칙<select id="pl-scope"><option value="static">정적 · 소스의 바깥 선언</option><option value="dynamic">동적 · 호출자 방향 가정</option></select></label>`+text('전역 x의 정수 값','x','1')+text('q의 지역 y · 정수 0~126','y','42');case 'memory':return `<label>관찰할 조건<select id="pl-memory"><option value="share">주소 공유 · y=x</option><option value="clone">별도 객체 복사 · 교육용 clone</option><option value="dangling">공유 후 free(x)</option><option value="garbage">x의 유일한 주소를 잃고 수집</option></select></label>`+text('처음 값','initial','1')+text('나중에 *y에 쓸 값','value','2');case 'block':return `<label>바깥 x 값<select id="pl-block"><option value="10">10</option><option value="20">20</option></select></label>`;case 'binding':return text('x의 첫 값','initial','5')+text('x에 새로 대입할 값','value','7');case 'overload':return `<label>호출 인자 타입<select id="pl-types"><option value="int,int">int, int</option><option value="double,int">double, int</option><option value="double,double">double, double</option><option value="int,double">int, double</option></select></label>`;}}
function scene(){return{frames:[],objects:[],rows:[],code:[],note:''};}
function build(kind,get){let s=scene(),events=[];const emit=(code,why,expected,choices,change)=>{change?.(s);events.push({state:copy(s),code,why,ask:'이 단계를 실행한 직후의 결과는?',expected:String(expected),choices:[...new Set([String(expected),...choices.map(String)])]});};const num=id=>{const n=Number(get(id));if(!Number.isFinite(n)||Math.abs(n)>1e6||!String(get(id)).trim())throw Error('정수 값을 -1000000~1000000 범위에서 입력하세요.');if(!Number.isInteger(n))throw Error('이 교육 모델에는 정수를 입력하세요.');return n;};
if(kind==='lexer'){const input=get('input');if(input.length>100)throw Error('입력은 100자 이내입니다.');s.text=input;s.tokens=[];let i=0;while(i<input.length){const start=i,c=input[i];if(/\s/.test(c)){while(i<input.length&&/\s/.test(input[i]))i++;emit('공백 건너뛰기','이 작은 scanner는 구분용 공백을 출력 토큰에서 제외합니다.','토큰 추가 없음',['NUMBER','ERROR'],v=>v.cursor=[start,i]);continue;}if(/[0-9]/.test(c)){while(i<input.length&&/[0-9]/.test(input[i]))i++;const value=input.slice(start,i);emit('숫자 누적: '+value,`누적식 이전값×10+새 자리로 ${value}를 인식합니다.`,'NUMBER('+value+')',['문자마다 별도 토큰','ERROR'],v=>{v.cursor=[start,i];v.tokens.push('NUMBER('+value+')');});}else if(/[a-zA-Z_]/.test(c)){while(i<input.length&&/[a-zA-Z0-9_]/.test(input[i]))i++;const value=input.slice(start,i);emit('최장 식별자 읽기: '+value,'영문자·숫자·밑줄이 이어지는 동안 하나로 모읍니다. 원문 scanner에 식별자 처리를 보충한 모델입니다.','ID('+value+')',['키워드로 무조건 분리','NUMBER'],v=>{v.cursor=[start,i];v.tokens.push('ID('+value+')');});}else{const name=({'*':'TIMES','+':'PLUS','(':'LPAREN',')':'RPAREN'})[c]||'ERROR';i++;emit('기호 분류: '+c,`현재 문자 ${c}를 ${name}로 분류하고 읽기 위치를 전진합니다.`,name,['NUMBER','토큰 추가 없음'],v=>{v.cursor=[start,i];v.tokens.push(name+'('+c+')');});}}emit('입력 끝','입력 문자를 모두 처리했습니다. 실제 C 코드의 실행이 아니라 유한 입력을 처리하는 작은 tokenizer 모델입니다.','입력 끝',['문자 재처리','파스 트리 완성'],v=>v.cursor=[input.length,input.length]);}
if(kind==='regex'){const value=get('input'),pattern=get('pattern');s.rows=[['입력',value],['전체 일치','검사 전']];const rules=pattern==='digits'?[['길이 1 이상',value.length>0],['모든 문자가 숫자',/^[0-9]*$/.test(value)]]:pattern==='id'?[['길이 1 이상',value.length>0],['첫 글자 영문자 또는 밑줄',/^[a-zA-Z_]/.test(value)],['이후 영숫자 또는 밑줄',/^[a-zA-Z0-9_]*$/.test(value.slice(1))]]:[['@ 기준 두 부분',value.split('@').length===2],['사용자명 영숫자 하나 이상',/^[a-zA-Z0-9]+$/.test(value.split('@')[0])],['도메인 영숫자·점·영문자 2개 이상',/^[a-zA-Z0-9]+\.[a-zA-Z]{2,}$/.test(value.split('@')[1]||'')]];rules.forEach(([label,pass])=>emit(label,'전체 일치 조건을 각각 검사합니다. 한 조건이라도 실패하면 전체 패턴과 일치하지 않습니다.',pass?'통과':'실패',[pass?'실패':'통과'],v=>v.rows.push([label,pass?'통과':'실패'])));const pass=rules.every(x=>x[1]);emit('전체 조건 합치기','앞 조건들을 모두 만족하는지 결합합니다.',pass?'전체 일치':'불일치',[pass?'불일치':'전체 일치'],v=>v.rows[1][1]=pass?'전체 일치':'불일치');}
if(kind==='derive'){const choice=get('sentence');const forms=choice==='list'?['<id_list>','<id>,<id_list>','a,<id_list>','a,<id>,<id_list>','a,b,<id_list>','a,b,<id>','a,b,c']:['sentence','noun-phrase verb-phrase .','article noun verb-phrase .',(choice==='dog'?'a':'the')+' noun verb-phrase .',(choice==='dog'?'a dog':'the girl')+' verb-phrase .',(choice==='dog'?'a dog':'the girl')+' verb noun-phrase .',(choice==='dog'?'a dog pets':'the girl sees')+' noun-phrase .',(choice==='dog'?'a dog pets':'the girl sees')+' article noun .',(choice==='dog'?'a dog pets the':'the girl sees a')+' noun .',choice==='dog'?'a dog pets the girl .':'the girl sees a dog .'];s.form=forms[0];forms.slice(1).forEach((f,i)=>emit('파생 '+(i+1),'현재 가장 왼쪽 비단말에 생성규칙 하나를 적용합니다. 이미 만들어진 단말의 순서는 유지합니다.',f,[forms[i],'모든 비단말을 한 번에 삭제'],v=>{v.previous=v.form;v.form=f;v.rows.push([String(i+1),f]);}));}
if(kind==='tree'){const input=get('input');if(!/^[0-9+*()\s]+$/.test(input)||input.length>80)throw Error('정수·+·*·괄호로 된 80자 이내 식을 입력하세요.');const ts=input.match(/\d+|[+*()]/g)||[];if(ts.filter(t=>/^\d/.test(t)).length>10)throw Error('숫자는 10개 이내로 입력하세요.');let at=0,seq=0;const nodes=[];function parse(min=0){const t=ts[at++];let a;if(t==='('){a=parse();if(ts[at++]!==')')throw Error('닫는 괄호가 필요합니다.');}else if(/^\d+$/.test(t||'')){if(!Number.isSafeInteger(Number(t)))throw Error('정수 리터럴이 안전한 범위를 넘었습니다.');a={id:'N'+(++seq),label:t,value:Number(t),leaf:true};nodes.push(a);}else throw Error('숫자 또는 여는 괄호가 필요한 위치입니다.');while(at<ts.length&&['+','*'].includes(ts[at])){const op=ts[at],prec=get('order')==='normal'?(op==='*'?2:1):(op==='+'?2:1);if(prec<min)break;at++;const b=parse(prec+1);a={id:'N'+(++seq),label:op,left:a,right:b};nodes.push(a);}return a;}const root=parse();if(at!==ts.length)throw Error('남은 입력 또는 괄호를 확인하세요.');s.tree=root;s.computed={};const post=node=>{if(node.leaf){emit('리터럴 '+node.label,'숫자 잎 노드의 값을 읽습니다.',node.value,['연산자','아직 값이 없음'],v=>{v.active=node.id;v.computed[node.id]=node.value;});return node.value;}const a=post(node.left),b=post(node.right),result=node.label==='+'?a+b:a*b;if(!Number.isSafeInteger(result))throw Error('이 모델의 안전한 정수 범위를 넘었습니다.');emit(`${a} ${node.label} ${b}`,`두 자식의 값 ${a}, ${b}가 준비되어 부모 ${node.label}를 계산합니다.`,result,[node.label==='+'?a*b:a+b,'아직 계산 불가'],v=>{v.active=node.id;v.computed[node.id]=result;});return result;};post(root);}
if(kind==='ebnf'){const path=get('path');if(path==='number'){const value=get('input');if(!/^\d{1,8}$/.test(value))throw Error('숫자를 1~8자리 입력하세요.');s.form='';[...value].forEach((c,i)=>emit(i?'반복 digit 통과':'필수 첫 digit 통과',i?'반복 경로를 한 번 더 돌아 숫자 한 자리를 추가합니다.':'반복 바깥의 첫 digit은 생략할 수 없습니다.',value.slice(0,i+1),[value.slice(0,i),'빈 문자열'],v=>v.form+=c));emit('반복 종료 후 출구','반복 횟수는 첫 필수 숫자를 제외한 추가 자리 수입니다.',value.length-1,[value.length,'0'],v=>v.rows=[['필수 통과',1],['추가 반복',value.length-1]]);}else{s.form='';['if',' (expr)',' stmt',...(path==='else'?[' else',' stmt']:[])].forEach(t=>emit('경로에서 '+t.trim()+' 읽기','else stmt는 함께 선택하거나 함께 생략합니다.',s.form+t,[s.form,'반드시 else 필요'],v=>v.form+=t));}}
if(kind==='scope'){const rule=get('scope'),gx=num('x'),qy=num('y');if(qy<0||qy>126)throw Error('q.y는 ASCII 비교를 위해 0~126 정수로 입력하세요.');s.frames=[{name:'전역',vars:[{name:'x',target:'Gx'},{name:'y',target:'Gy'}]}];s.objects=[{id:'Gx',value:gx,alive:true},{id:'Gy',value:'a',alive:true}];s.rows=[];emit('main 진입 · char x=b','main의 x는 전역 x와 다른 객체입니다.','main.x',['전역.x','p.x'],v=>{v.frames.push({name:'main',vars:[{name:'x',target:'Mx'}]});v.objects.push({id:'Mx',value:'b',alive:true});});emit('q 진입 · int y='+qy,'q의 y는 main의 지역 x와 다른 이름입니다.','q.y',['전역.y','main.x'],v=>{v.frames.push({name:'q',vars:[{name:'y',target:'Qy'}]});v.objects.push({id:'Qy',value:qy,alive:true});});emit('q에서 x 조회',rule==='static'?'q를 소스상 둘러싼 전역에서 x를 찾습니다.':'q에 x가 없어 호출자 main의 x를 찾습니다.',rule==='static'?'전역.x':'main.x',['전역.x','main.x','q.y'],v=>{v.selected=rule==='static'?'Gx':'Mx';v.rows.push(['q의 정수 출력',rule==='static'?gx:'98 (ASCII b)']);});emit('p 진입 · double x=2.5','p의 지역 x가 추가됩니다. y 탐색과 x 선언을 구분하세요.','p.x',['전역.x','main.x'],v=>{v.frames.push({name:'p',vars:[{name:'x',target:'Px'}]});v.objects.push({id:'Px',value:2.5,alive:true});});emit('p에서 y 조회',rule==='static'?'p의 소스상 바깥은 전역이므로 y=a입니다.':'호출자 q의 y를 먼저 찾습니다.',rule==='static'?'전역.y':'q.y',['전역.y','q.y','main.x'],v=>{v.selected=rule==='static'?'Gy':'Qy';v.rows.push(['p의 문자 출력',rule==='static'?'a':String.fromCharCode(qy)+' (ASCII '+qy+')']);});emit('p 반환','p의 지역 객체 수명이 끝나며 현재 호출은 q로 돌아갑니다.','q',['main','p'],v=>{v.frames.pop();v.objects.find(o=>o.id==='Px').alive=false;v.selected=null;});}
if(kind==='memory'){const condition=get('memory'),a=num('initial'),b=num('value');s.frames=[{name:'포인터 환경',vars:[{name:'x',target:null},{name:'y',target:null}]}];const vars=s.frames[0].vars;emit('x = malloc(sizeof(int))','할당 성공을 가정해 새 정수 객체 H1을 만듭니다. 값은 아직 초기화하지 않았습니다.','H1',['null','정수 '+a],v=>{v.objects.push({id:'H1',value:'?',alive:true});v.frames[0].vars[0].target='H1';});emit('*x = '+a,'x의 주소를 따라 H1의 내용을 바꿉니다.',a,['주소가 '+a+'로 바뀜','객체 해제'],v=>v.objects[0].value=a);if(condition==='garbage'){emit('x = null','마지막 접근 경로를 잃어도 객체는 아직 해제되지 않았습니다.','접근 불가·살아 있음',['해제됨','y가 자동 연결'],v=>{v.frames[0].vars[0].target=null;v.objects[0].garbage=true;});emit('교육용 collect()','접근 불가 객체를 즉시 회수하는 단순 수집 모델입니다. 실제 C에 collect 함수가 있다는 뜻은 아닙니다.','해제됨',['값 0','x로 다시 연결'],v=>v.objects[0].alive=false);}else{const clone=condition==='clone';emit(clone?'y = clone_object(x)':'y = x',clone?'교육용 복사 연산으로 H2를 새로 만들고 값을 복사합니다.':'주소를 복사하므로 y도 H1에 연결됩니다.',clone?'H2':'H1',['H1','H2','값만 0'],v=>{if(clone)v.objects.push({id:'H2',value:a,alive:true});v.frames[0].vars[1].target=clone?'H2':'H1';});emit('*y = '+b,clone?'y의 별도 객체 H2만 바뀝니다.':'x와 y가 공유하는 H1이 바뀝니다.',clone?'H2 변경':'H1 변경',['H1 변경','H2 변경','포인터 해제'],v=>v.objects.find(o=>o.id===(clone?'H2':'H1')).value=b);if(condition==='dangling')emit('free(x)','객체 H1의 수명이 끝납니다. y의 참조는 자동으로 안전해지지 않습니다.','H1 해제',['y가 H2로 이동','값 0'],v=>v.objects[0].alive=false);emit('읽기: *'+(condition==='dangling'?'y':'x'),condition==='dangling'?'해제된 객체 읽기는 유효한 숫자로 결과를 정하지 않습니다.':clone?'x는 H1을 유지했으므로 원래 값을 읽습니다.':'두 이름이 같은 객체를 공유하므로 변경값을 읽습니다.',condition==='dangling'?'유효한 읽기 불가':clone?a:b,[a,b,'유효한 읽기 불가'],v=>{v.selected=condition==='dangling'?v.frames[0].vars[1].target:v.frames[0].vars[0].target;v.rows=[['읽기 결과',condition==='dangling'?'유효한 읽기 불가':clone?a:b]];});}}
if(kind==='block'){const a=+get('block');s.frames=[{name:'A',vars:[{name:'x',target:'Ax'},{name:'y',target:'Ay'}]}];s.objects=[{id:'Ax',value:a,alive:true},{id:'Ay',value:'a',alive:true}];const enter=(name,vars)=>{s.frames.push({name,vars:vars.map(([n,value])=>({name:n,target:name+n}))});vars.forEach(([n,value])=>s.objects.push({id:name+n,value,alive:true}));};const exit=()=>{const f=s.frames.pop();f.vars.forEach(v=>s.objects.find(o=>o.id===v.target).alive=false);};emit('B 진입: double x, int a','안쪽 x가 같은 이름을 가리지만 A.x는 살아 있습니다.','B.x',['A.x','x 없음'],()=>enter('B',[['x',2.5],['a',1]]));emit('B 종료','B.x 수명이 끝나고 바깥 x가 다시 선택됩니다.','A.x',['B.x','x 없음'],()=>exit());emit('C 진입: char y, int b','C에는 x가 없으므로 x는 여전히 A.x입니다.','A.x',['C.x','B.x'],()=>enter('C',[['y','c'],['b',2]]));emit('D 진입: int x, double y','D 안의 x와 y가 각각 바깥 이름을 가립니다.','D.x',['A.x','C.y'],()=>enter('D',[['x',3],['y',4.5]]));emit('D 종료','C에는 x가 없으므로 A.x로, y는 C.y로 복원됩니다.','A.x',['D.x','B.x'],()=>exit());emit('C 종료','C 객체 수명이 끝나고 A의 이름 연결이 남습니다.','A.y',['C.y','D.y'],()=>exit());}
if(kind==='binding'){const a=num('initial'),b=num('value');s.frames=[{name:'환경 E',vars:[]}];emit('int x = '+a,'이름 x를 저장 위치 L1에 연결하고 내용을 초기화합니다.','x→L1',['x→L2','객체 없음'],v=>{v.frames[0].vars.push({name:'x',target:'L1'});v.objects.push({id:'L1',value:a,alive:true});});emit('x = '+b,'위치 연결은 유지하고 메모리 L1의 값만 바뀝니다.',b,[a,'L2 생성'],v=>v.objects[0].value=b);emit('M(E(x)) 조회','E(x)=L1을 찾고 M(L1)을 읽습니다.',b,[a,'이름 x 자체'],v=>{v.selected='L1';v.rows=[['E(x)','L1'],['M(L1)',b]];});}
if(kind==='overload'){const t=get('types');s.rows=[['후보1','int sum(int,int)'],['후보2','double sum(double,int)'],['후보3','double sum(double,double)']];emit('인자 개수 검사','선택한 입력은 모두 2개라 세 후보 모두 개수 조건을 통과합니다.','후보 3개',['후보 1개','후보 0개'],v=>v.rows.push(['개수 조건','모두 2개']));const exact=({'int,int':'후보1','double,int':'후보2','double,double':'후보3'})[t]||'직접 일치 없음';emit('변환 없는 타입 일치 검사','이 모델은 먼저 직접 일치만 비교합니다. 직접 일치가 없을 때 실제 언어의 변환·모호성 판정은 별도 문제입니다.',exact,['후보1','후보2','후보3','직접 일치 없음'],v=>v.rows.push(['직접 일치',exact]));}
return{initial:sceneForInitial(kind,events,s),events};
}
function sceneForInitial(kind,events,final){if(['scope','block'].includes(kind)){const s=copy(events[0].state);s.frames=s.frames.slice(0,1);s.objects=s.objects.filter(o=>s.frames[0].vars.some(v=>v.target===o.id));s.rows=[];return s;}if(kind==='memory'){const s=scene();s.frames=[{name:'포인터 환경',vars:[{name:'x',target:null},{name:'y',target:null}]}];return s;}if(kind==='lexer')return{...scene(),text:final.text,tokens:[]};if(kind==='tree')return{...scene(),tree:final.tree,computed:{}};if(kind==='derive')return{...scene(),form:final.rows[0]?.[1]?.startsWith('<')?'<id_list>':'sentence'};return scene();}
function graph(s,previous){if(s.tree)return treeSVG(s);const frames=s.frames||[],objects=s.objects||[];if(!frames.length)return '';const vars=frames.flatMap(f=>f.vars.map(v=>({...v,frame:f.name}))),height=Math.max(220,60+Math.max(vars.length,objects.length)*52),old=previous?.objects||[];return `<svg class="pl-graph" viewBox="0 0 760 ${height}" role="img" aria-label="이름 환경과 객체 메모리의 연결도"><defs><marker id="pl-arrow" markerWidth="8" markerHeight="8" refX="8" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6" fill="#087f84"/></marker></defs><text x="25" y="25">이름·선언 영역</text><text x="480" y="25">객체·값·수명</text>${vars.map((v,i)=>{const y=45+i*52,j=objects.findIndex(o=>o.id===v.target),o=objects[j];return `${o?`<path d="M280 ${y+19} C370 ${y+19},390 ${64+j*52},480 ${64+j*52}" class="${o.alive?'':'dead'}" marker-end="url(#pl-arrow)"/>`:''}<rect x="20" y="${y}" width="260" height="38" rx="6"/><text x="32" y="${y+25}">${esc(v.frame+'.'+v.name)} → ${esc(v.target||'? / null')}</text>`;}).join('')}${objects.map((o,i)=>{const y=45+i*52,changed=!old.some(v=>JSON.stringify(v)===JSON.stringify(o));return `<rect class="${!o.alive?'dead':changed?'changed':''} ${s.selected===o.id?'selected':''}" x="480" y="${y}" width="250" height="38" rx="6"/><text x="492" y="${y+25}">${esc(o.id)}: ${esc(o.value)} · ${!o.alive?'已해제'.replace('已',''):o.garbage?'접근 불가':'살아 있음'}</text>`;}).join('')}</svg>`;}
function treeSVG(s){const positions=[],lines=[];let leaf=0;function layout(node,depth){let x;if(node.leaf)x=60+(leaf++)*65;else{const a=layout(node.left,depth+1),b=layout(node.right,depth+1);x=(a+b)/2;lines.push([x,depth*80+40,a,(depth+1)*80+40],[x,depth*80+40,b,(depth+1)*80+40]);}positions.push({node,x,y:depth*80+40});return x;}layout(s.tree,0);const w=Math.max(350,leaf*65+60),h=Math.max(...positions.map(p=>p.y))+60;return `<svg class="pl-graph" viewBox="0 0 ${w} ${h}" role="img" aria-label="입력 식의 AST와 단계별 계산 결과">${lines.map(l=>`<line x1="${l[0]}" y1="${l[1]}" x2="${l[2]}" y2="${l[3]}"/>`).join('')}${positions.map(({node,x,y})=>`<circle class="${s.active===node.id?'changed':''}" cx="${x}" cy="${y}" r="24"/><text x="${x}" y="${y+5}" text-anchor="middle">${esc(node.label)}</text>${s.computed[node.id]!==undefined?`<text x="${x+27}" y="${y}" class="pl-value">=${s.computed[node.id]}</text>`:''}`).join('')}</svg>`;}
function draw(s,prev){return `${s.text!==undefined?`<div class="pl-characters">${[...s.text].map((c,i)=>`<span class="${s.cursor&&i>=s.cursor[0]&&i<s.cursor[1]?'changed':''}">${c===' '?'␣':esc(c)}</span>`).join('')}</div><div class="pl-tokens">${s.tokens.map(t=>`<span>${esc(t)}</span>`).join('')||'아직 출력 토큰 없음'}</div>`:''}${s.form!==undefined?`<pre class="pl-form">${esc(s.form||'아직 읽은 부분 없음')}</pre>`:''}${graph(s,prev)}${s.rows?.length?`<table><thead><tr><th>관찰 항목</th><th>현재 결과</th></tr></thead><tbody>${s.rows.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table>`:''}`;}
function mount(root,ch,n,onAnswer){cleanup();const kind=mode(ch,n);if(!kind){root.innerHTML='';return;}let timeline,index=0,timer=null,predictions={},lastChoice=null;root.innerHTML=`<section class="pl-lab"><h3>${titles[kind]}</h3><p class="pl-model-note">교육용 모델</p><details><summary>실험 조건 바꾸기</summary><div class="pl-inputs">${controls(kind,ch,n)}</div><button type="button" id="pl-apply" class="s-btn">조건 적용·처음부터</button></details><p id="pl-error" role="alert"></p><div class="pl-stepbar"><button id="pl-reset" class="s-btn">초기화</button><button id="pl-prev" class="s-btn">이전 단계</button><button id="pl-next" class="s-btn teal">다음 단계</button><button id="pl-play" class="s-btn">자동 재생</button><button id="pl-zoom" class="s-btn">도표 확대</button><span id="pl-counter"></span></div><div id="pl-visual"></div><div id="pl-why" role="status" aria-live="polite"></div><section class="pl-predict"><h4 id="pl-question"></h4><label>실행 전 예상<select id="pl-prediction"><option value="">먼저 선택하세요</option></select></label><button id="pl-check" class="s-btn">예측 후 한 단계 실행·비교</button><div id="pl-comparison" role="status"></div></section><details><summary>단계별 동작 기록</summary><ol id="pl-history"></ol></details></section>`;const q=s=>root.querySelector(s),get=id=>q('#pl-'+id)?.value;const stop=()=>{clearInterval(timer);timer=null;q('#pl-play').textContent='자동 재생';};
function render(){const s=index?timeline.events[index-1].state:timeline.initial,prev=index>1?timeline.events[index-2].state:timeline.initial;q('#pl-visual').innerHTML=draw(s,prev);q('#pl-counter').textContent=`${index} / ${timeline.events.length}단계`;q('#pl-prev').disabled=index===0;q('#pl-next').disabled=q('#pl-play').disabled=index>=timeline.events.length;const e=index?timeline.events[index-1]:null;q('#pl-why').innerHTML=e?`<b>${esc(e.code)}</b><p>${esc(e.why)}</p><p>현재 관찰 결과: <b>${esc(e.expected)}</b></p>`:'<p>시작 전입니다. 다음 동작의 결과를 먼저 예측하거나 다음 단계로 진행하세요.</p>';const next=timeline.events[index];q('#pl-question').textContent=next?next.code+' — '+next.ask:'모든 단계를 마쳤습니다.';q('#pl-prediction').innerHTML='<option value="">먼저 선택하세요</option>'+(next?[...next.choices].sort((a,b)=>a.localeCompare(b,'ko')).map(c=>`<option>${esc(c)}</option>`).join(''):'');q('#pl-check').disabled=!next;q('#pl-history').innerHTML=timeline.events.slice(0,index).map(e=>`<li><b>${esc(e.code)}</b> — ${esc(e.why)}</li>`).join('');}
function reset(){stop();try{timeline=build(kind,get);index=0;predictions={};q('#pl-error').textContent='';q('#pl-comparison').textContent='';render();}catch(e){q('#pl-error').textContent=e.message;q('#pl-visual').innerHTML='';q('#pl-why').textContent='입력 조건을 수정한 뒤 다시 적용하세요.';q('#pl-prev').disabled=true;q('#pl-next').disabled=q('#pl-play').disabled=q('#pl-check').disabled=true;}}
q('#pl-apply').onclick=reset;root.querySelectorAll('.pl-inputs input,.pl-inputs select').forEach(el=>el.onchange=reset);q('#pl-reset').onclick=reset;q('#pl-prev').onclick=()=>{stop();index=Math.max(0,index-1);q('#pl-comparison').textContent='';render();};q('#pl-next').onclick=()=>{stop();index=Math.min(timeline.events.length,index+1);q('#pl-comparison').textContent='';render();};q('#pl-play').onclick=()=>{if(timer){stop();return;}q('#pl-play').textContent='일시 정지';timer=setInterval(()=>{index++;render();if(index>=timeline.events.length)stop();},1600);};q('#pl-check').onclick=()=>{const choice=q('#pl-prediction').value;if(!choice){q('#pl-comparison').textContent='예상 결과를 먼저 선택하세요.';return;}stop();const e=timeline.events[index],correct=choice===e.expected;const result={kind,question:e.code+' — '+e.ask,choice,expected:e.expected,correct,why:e.why};onAnswer?.(kind+':'+e.code+':'+e.expected,result);index++;render();q('#pl-comparison').innerHTML=`<b>${correct?'예상과 같습니다.':'예상과 다릅니다.'}</b><p>예상: ${esc(choice)} / 실제: ${esc(e.expected)}</p><p>${esc(e.why)}</p>`;};q('#pl-zoom').onclick=()=>{const el=q('#pl-visual');if(document.fullscreenElement)document.exitFullscreen();else el.requestFullscreen?.().catch(()=>{el.classList.toggle('pl-expanded');});};cleanup=stop;reset();}
window.PLLab={mount,stop:()=>cleanup(),build,mode};
})();
